import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = config.id || 'home-divider';

  // --- Load cached GLB mesh ----------------------------------------------
  const meshUrl = config.assets?.meshUrl;
  const gltf = meshUrl ? ctx.glbLoader(meshUrl) : null;
  const meshRoot = gltf ? (gltf.scene || gltf) : new THREE.Group();

  // Apply authored scene placement onto the wrapper group; preserve mesh-local transform.
  const placement = config.scenePlacement || {};
  const pos = placement.position || [-2.5, 0.7, 0];
  const rot = placement.rotation || [0, 0, 0];
  const scl = placement.scale || [1, 1, 1];

  group.position.set(pos[0], pos[1], pos[2]);
  group.rotation.set(rot[0], rot[1], rot[2]);
  group.scale.set(scl[0], scl[1], scl[2]);

  group.add(meshRoot);

  // --- State -------------------------------------------------------------
  const timelines = [];
  const originalLocalY = meshRoot.position.y;
  const targetLift = 0.15; // subtle rise-in
  let hovered = false;
  let focused = false;

  // Collect any emissive-capable materials for focus accent edge.
  const emissiveMats = [];
  meshRoot.traverse((obj) => {
    if (obj.isMesh && obj.material) {
      const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
      mats.forEach((m) => {
        if (m && ('emissive' in m || 'emissiveNode' in m)) {
          emissiveMats.push(m);
          if (m.userData && m.userData.__novaAccentEmissive == null) {
            m.userData.__novaAccentEmissive = m.emissiveIntensity ?? 0;
          }
        }
      });
    }
  });

  // --- Interaction handlers ---------------------------------------------
  const onHoverEnter = () => {
    if (hovered) return;
    hovered = true;
    const tl = gsap.timeline();
    tl.to(meshRoot.position, {
      y: originalLocalY + targetLift,
      duration: 0.7,
      ease: 'power3.out',
    });
    timelines.push(tl);
  };

  const onHoverLeave = () => {
    if (!hovered) return;
    hovered = false;
    const tl = gsap.timeline();
    tl.to(meshRoot.position, {
      y: originalLocalY,
      duration: 0.5,
      ease: 'power2.out',
    });
    timelines.push(tl);
  };

  const onFocus = () => {
    if (focused) return;
    focused = true;
    const tl = gsap.timeline();
    emissiveMats.forEach((m) => {
      const base = (m.userData && m.userData.__novaAccentEmissive) ?? 0;
      tl.to(m, {
        emissiveIntensity: Math.max(base, 1.0),
        duration: 0.4,
        ease: 'power2.out',
      }, 0);
    });
    timelines.push(tl);
  };

  const onBlur = () => {
    if (!focused) return;
    focused = false;
    const tl = gsap.timeline();
    emissiveMats.forEach((m) => {
      const base = (m.userData && m.userData.__novaAccentEmissive) ?? 0;
      tl.to(m, {
        emissiveIntensity: base,
        duration: 0.4,
        ease: 'power2.out',
      }, 0);
    });
    timelines.push(tl);
  };

  const onClick = () => {
    // press-down weighted-settle
    const tl = gsap.timeline();
    tl.to(meshRoot.scale, {
      x: scl[0] * 0.97,
      y: scl[1] * 0.97,
      z: scl[2] * 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
    });
    tl.to(meshRoot.scale, {
      x: scl[0],
      y: scl[1],
      z: scl[2],
      duration: 0.2,
      ease: 'power2.out',
    });
    tl.to(meshRoot.position, {
      y: originalLocalY + (hovered ? targetLift : 0),
      duration: 0.5,
      ease: 'power3.out',
    }, '<');
    timelines.push(tl);

    // Emit selection event on parent hub.
    if (ctx.emit) {
      ctx.emit('hub-home.select', {
        source: config.id,
        node: group.name,
        timestamp: performance.now(),
      });
    }
  };

  // --- Data binding wiring (declarative only; mutation triggered upstream)
  group.userData.bindings = (config.dataBindings || []).map((b) => ({
    source: b.source,
    target: b.target,
  }));

  // --- Expose handlers for the prism event bus ---------------------------
  group.userData.handlers = {
    hoverEnter: onHoverEnter,
    hoverLeave: onHoverLeave,
    focus: onFocus,
    blur: onBlur,
    click: onClick,
  };

  // --- Cleanup -----------------------------------------------------------
  group.userData.cleanup = () => {
    while (timelines.length) {
      const tl = timelines.pop();
      try { tl.kill(); } catch (_) {}
    }
    group.traverse((obj) => {
      if (obj.geometry && obj.geometry.dispose) obj.geometry.dispose();
      if (obj.material) {
        const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
        mats.forEach((m) => { if (m && m.dispose) m.dispose(); });
      }
    });
  };

  return group;
}
